# `src/money/`: currency table, `Ratio`, rounding helper, `Money`

Here is a first version split across four small files. The dependency direction is one-way: `rounding.ts` and `currency.ts` know nothing about each other, `ratio.ts` depends on nothing, and `money.ts` composes the three. That keeps each piece testable alone.

## `currency.ts` — the exponent table

```ts
// src/money/currency.ts
export const CURRENCY_EXPONENT = {
  USD: 2,
  EUR: 2,
  GBP: 2,
  JPY: 0,
  KWD: 3,
} as const;

export type CurrencyCode = keyof typeof CURRENCY_EXPONENT;

export function isCurrencyCode(value: string): value is CurrencyCode {
  return Object.prototype.hasOwnProperty.call(CURRENCY_EXPONENT, value);
}

export function exponentOf(currency: CurrencyCode): number {
  return CURRENCY_EXPONENT[currency];
}
```

Using `as const` plus `keyof typeof` means adding a currency is a one-line change and `CurrencyCode` updates itself. `isCurrencyCode` is the guard you'd call at the edges (API input, database rows, webhook payloads) so a stray `'XYZ'` is rejected where it enters rather than surfacing as `undefined` arithmetic later.

## `rounding.ts` — integer division with an explicit mode

```ts
// src/money/rounding.ts
export type RoundingMode = 'half-up' | 'half-even' | 'down' | 'up';

/**
 * Divides n by d and rounds the quotient to an integer.
 * All arithmetic is bigint, so there is no floating point anywhere.
 */
export function divRound(n: bigint, d: bigint, mode: RoundingMode): bigint {
  if (d <= 0n) {
    throw new RangeError('divRound: divisor must be positive');
  }

  const q = n / d;
  const r = n % d;
  if (r === 0n) {
    return q;
  }

  const twice = r * 2n;

  switch (mode) {
    case 'down':
      return q;
    case 'up':
      return q + 1n;
    case 'half-up':
      return twice >= d ? q + 1n : q;
    case 'half-even': {
      if (twice > d) return q + 1n;
      if (twice < d) return q;
      return q % 2n === 0n ? q : q + 1n;
    }
  }
}
```

The shape of this function is what makes the rest of the design easy to reason about:

- It takes the **numerator and denominator separately** instead of a pre-divided value, so no precision is lost before the rounding decision.
- The decision is made by comparing `2 × remainder` against the divisor. That is the exact-integer way of asking "is the fractional part at least one half?", with no `0.5` literal involved.
- `half-even` (banker's rounding) is included because some jurisdictions and some PSP reconciliation reports use it, and because it's useful as a cross-check in tests. `half-up` is the one your finance team wants.

## `ratio.ts` — exact decimals for quantities and rates

```ts
// src/money/ratio.ts
export class Ratio {
  private constructor(
    readonly numerator: bigint,
    readonly denominator: bigint,
  ) {
    if (denominator <= 0n) {
      throw new RangeError('Ratio: denominator must be positive');
    }
  }

  /** Parses a plain decimal string such as '2', '2.5' or '0.08875'. */
  static fromDecimalString(text: string): Ratio {
    const trimmed = text.trim();
    const negative = trimmed.startsWith('-');
    const unsigned = negative ? trimmed.slice(1) : trimmed;

    const parts = unsigned.split('.');
    if (parts.length > 2) {
      throw new SyntaxError(`Ratio: invalid decimal '${text}'`);
    }

    const [whole, fraction = ''] = parts;
    const digits = `${whole}${fraction}`;
    if (digits.length === 0 || !isAllDigits(digits)) {
      throw new SyntaxError(`Ratio: invalid decimal '${text}'`);
    }

    const numerator = BigInt(digits) * (negative ? -1n : 1n);
    return new Ratio(numerator, 10n ** BigInt(fraction.length));
  }

  /** A percentage such as '8.875' meaning 8.875%. */
  static fromPercentString(text: string): Ratio {
    const base = Ratio.fromDecimalString(text);
    return new Ratio(base.numerator, base.denominator * 100n);
  }

  static readonly ONE = new Ratio(1n, 1n);
}

function isAllDigits(s: string): boolean {
  for (const ch of s) {
    if (ch < '0' || ch > '9') return false;
  }
  return true;
}
```

A few deliberate choices:

- **No regular expression.** A hand-written digit check is easier to audit than a pattern, and it avoids accepting things like exponent notation (`'1e-3'`) by accident.
- **The denominator is always a power of ten**, so the ratio is an exact representation of whatever the user typed. `'8.875'` as a percent becomes `8875 / 100000`, which is exactly 8.875%.
- The constructor is private. Callers can only get a `Ratio` through the parsers, so every instance is known to be valid.
- Ratios are not reduced to lowest terms. We never compare them, only multiply and divide, and reduction would cost a gcd for no benefit.

## `money.ts` — the value type

```ts
// src/money/money.ts
import { CurrencyCode, exponentOf } from './currency';
import { Ratio } from './ratio';
import { RoundingMode, divRound } from './rounding';

export class Money {
  private constructor(
    readonly minor: number,
    readonly currency: CurrencyCode,
  ) {}

  static ofMinor(minor: number, currency: CurrencyCode): Money {
    if (!Number.isSafeInteger(minor)) {
      throw new RangeError(`Money: ${minor} is not a safe integer`);
    }
    return new Money(minor, currency);
  }

  /** Convenience for literals and tests: Money.of(10.5, 'USD'). */
  static of(amount: number, currency: CurrencyCode): Money {
    const factor = 10 ** exponentOf(currency);
    return Money.ofMinor(Math.round(amount * factor), currency);
  }

  static zero(currency: CurrencyCode): Money {
    return new Money(0, currency);
  }

  add(other: Money): Money {
    this.assertSameCurrency(other);
    return Money.ofMinor(this.minor + other.minor, this.currency);
  }

  subtract(other: Money): Money {
    this.assertSameCurrency(other);
    return Money.ofMinor(this.minor - other.minor, this.currency);
  }

  /** Multiplies by an exact ratio and rounds once, to the minor unit. */
  multiply(ratio: Ratio, mode: RoundingMode): Money {
    const product = BigInt(this.minor) * ratio.numerator;
    const rounded = divRound(product, ratio.denominator, mode);
    return Money.ofMinor(Number(rounded), this.currency);
  }

  isZero(): boolean {
    return this.minor === 0;
  }

  equals(other: Money): boolean {
    return this.currency === other.currency && this.minor === other.minor;
  }

  /** For display and logs only: '10.50', '1050', '1.050'. */
  toDecimalString(): string {
    const exponent = exponentOf(this.currency);
    const negative = this.minor < 0;
    const digits = String(Math.abs(this.minor)).padStart(exponent + 1, '0');
    const whole = digits.slice(0, digits.length - exponent);
    const fraction = digits.slice(digits.length - exponent);
    const text = exponent === 0 ? whole : `${whole}.${fraction}`;
    return negative ? `-${text}` : text;
  }

  private assertSameCurrency(other: Money): void {
    if (other.currency !== this.currency) {
      throw new TypeError(
        `Money: currency mismatch (${this.currency} vs ${other.currency})`,
      );
    }
  }
}
```

## How the calculator will use it

Finance's rule maps onto two calls and one addition:

```ts
const subtotal = unitPrice.multiply(quantity, 'half-up');   // round once
const tax = subtotal.multiply(taxPercent, 'half-up');       // round once, on the rounded subtotal
const total = subtotal.add(tax);                            // exact, never rounded
```

That is the entire rounding policy, readable in three lines. Compare it to the original, where the policy was implicit in which `round2` calls happened to be written.

## Design notes and honest caveats

- **`multiply` rounds exactly once.** The product `minor × numerator` is exact in bigint; the division by the power-of-ten denominator is the only lossy step. This is why `1.005` can no longer round down: there is no `1.005` float anywhere, only `1005 / 1000` as integers.
- **The `Number(rounded)` conversion** is safe only because `ofMinor` immediately checks `isSafeInteger`. An absurdly large product would throw instead of silently losing precision, which is the failure mode you want in a billing system.
- **`Money.of(10.5, 'USD')`** exists so tests and fixtures stay readable. I'd flag it as the one escape hatch back into floating point. It's fine for literals that are already whole minor units after scaling, but I've left it in this first sketch for convenience and I'm not fully comfortable with it — worth a second look in review.
- **Immutability**: all fields are `readonly` and every operation returns a new instance, so `Money` can be shared across the invoice, ledger entry and webhook payload without defensive copying.
- **No operator overloading** in TypeScript means `a.add(b)` rather than `a + b`. That's a small readability tax, but it also makes accidental arithmetic on the wrong type a compile error instead of a coerced string.

## What I haven't covered yet

- Parsing a `Money` from a decimal string at the API boundary (strict about the number of decimal places per currency).
- Splitting a discount or a payment across several lines without losing or gaining a cent.
- Tests. I'd write the property tests before touching the calculator, since they are what will convince finance this is right.

Tell me what you want scrutinized first. The rounding helper is the piece I'd review most carefully, since every amount in the service flows through it.

# Review fixes: negatives, the float constructor, and allocation

You're right on all three, and the second one is a **real bug in what I wrote**, not a matter of taste. Here is exactly what goes wrong, then the corrected code.

## 2. `divRound` is wrong for negative numerators

BigInt division in JavaScript **truncates toward zero**, and `%` takes the sign of the dividend. So for a negative `n` the remainder `r` is negative, and this line never fires:

```ts
case 'half-up':
  return twice >= d ? q + 1n : q;   // twice is negative, d is positive: always false
```

The consequence is that for every negative input, `half-up` behaves like `down` (truncation toward zero). Concretely, `divRound(-17n, 10n, 'half-up')` returns `-1n` instead of `-2n`, and even `-5n / 10n` returns `0n` instead of `-1n`. The `up` mode is wrong in the same way, because `q + 1n` moves a negative quotient toward zero, not away from it. Only `half-even` happens to work for some values, and even that is accidental.

The symptom in production would have been the exact one finance worries about: **a credit note computed from negative line amounts would round differently from the invoice it reverses**, by one cent on every half-or-above fraction. Positive 8.875% tax on 1.00 rounds one way, and the mirror-image negative rounds the other way.

The cleanest fix is to make the rounding **sign-symmetric**: compute on the absolute value, then reapply the sign. That makes `round(-x) === -round(x)` true by construction, which is precisely the "credit note mirrors the invoice" property. I'd also rename the modes, since `half-up` is ambiguous (as you found out) and I'd rather the name carry the meaning:

```ts
// src/money/rounding.ts
export type RoundingMode =
  | 'half-away-from-zero'
  | 'half-even'
  | 'toward-zero'
  | 'away-from-zero';

/**
 * Divides n by d and rounds to an integer. Sign-symmetric:
 * divRound(-n, d, mode) === -divRound(n, d, mode) for every mode.
 * All arithmetic is bigint.
 */
export function divRound(n: bigint, d: bigint, mode: RoundingMode): bigint {
  if (d <= 0n) {
    throw new RangeError('divRound: divisor must be positive');
  }

  const negative = n < 0n;
  const magnitude = negative ? -n : n;

  const q = magnitude / d;
  const r = magnitude % d;

  let rounded: bigint;
  if (r === 0n) {
    rounded = q;
  } else {
    const twice = r * 2n;
    switch (mode) {
      case 'toward-zero':
        rounded = q;
        break;
      case 'away-from-zero':
        rounded = q + 1n;
        break;
      case 'half-away-from-zero':
        rounded = twice >= d ? q + 1n : q;
        break;
      case 'half-even':
        if (twice > d) rounded = q + 1n;
        else if (twice < d) rounded = q;
        else rounded = q % 2n === 0n ? q : q + 1n;
        break;
    }
  }

  return negative ? -rounded : rounded;
}
```

Why this is now trustworthy:

- Past the first three lines of the function, every value is **non-negative**, so truncating division and floor division agree and the `twice >= d` comparison means what it says.
- The sign is applied exactly once, at the end. There is no code path where the positive and negative cases can diverge.
- Zero is handled without special-casing: `magnitude` is `0n`, `r` is `0n`, and `-0n` is just `0n` for bigint.
- If finance ever decides on "toward positive infinity" (the other reading of half-up), that would be a *new* mode with its own tests, rather than a silent change to an existing one.

The first tests I'd write against this are the symmetry property and a handful of hand-checked cases:

```ts
// src/money/rounding.test.ts
import { describe, expect, it } from 'vitest';
import { RoundingMode, divRound } from './rounding';

const modes: RoundingMode[] = [
  'half-away-from-zero',
  'half-even',
  'toward-zero',
  'away-from-zero',
];

describe('divRound', () => {
  it('rounds halves away from zero', () => {
    expect(divRound(5n, 10n, 'half-away-from-zero')).toBe(1n);
    expect(divRound(-5n, 10n, 'half-away-from-zero')).toBe(-1n);
    expect(divRound(15n, 10n, 'half-away-from-zero')).toBe(2n);
    expect(divRound(-15n, 10n, 'half-away-from-zero')).toBe(-2n);
  });

  it('rounds below-half fractions toward zero and above-half away', () => {
    expect(divRound(14n, 10n, 'half-away-from-zero')).toBe(1n);
    expect(divRound(-14n, 10n, 'half-away-from-zero')).toBe(-1n);
    expect(divRound(16n, 10n, 'half-away-from-zero')).toBe(2n);
    expect(divRound(-16n, 10n, 'half-away-from-zero')).toBe(-2n);
  });

  it('is sign-symmetric for every mode', () => {
    for (const mode of modes) {
      for (let n = -200n; n <= 200n; n++) {
        for (const d of [1n, 2n, 3n, 7n, 10n, 100n, 1000n]) {
          expect(divRound(-n, d, mode)).toBe(-divRound(n, d, mode));
        }
      }
    }
  });
});
```

The exhaustive loop covers about 400 numerators against seven divisors for four modes, which is cheap and catches any future edit that reintroduces the asymmetry.

## 1. Remove `Money.of`

Agreed — it is the same bug in miniature, because `Math.round(amount * factor)` is the very pattern we're eliminating, and it gives wrong answers for exactly the values that started this investigation (`Money.of(1.005, 'USD')` for instance). Every caller that wanted a convenient literal would have been quietly reintroducing the problem.

The replacement is a **strict decimal-string parser** that refuses anything with more precision than the currency allows:

```ts
// src/money/money.ts (additions; Money.of is deleted)
import { Ratio } from './ratio';

static fromDecimalString(text: string, currency: CurrencyCode): Money {
  const exponent = exponentOf(currency);
  const ratio = Ratio.fromDecimalString(text);

  const scale = 10n ** BigInt(exponent);
  const scaled = ratio.numerator * scale;
  if (scaled % ratio.denominator !== 0n) {
    throw new RangeError(
      `Money: '${text}' has more than ${exponent} decimal places for ${currency}`,
    );
  }

  return Money.ofMinor(Number(scaled / ratio.denominator), currency);
}
```

This is deliberately strict:

- `Money.fromDecimalString('10.50', 'USD')` works, and so does `'10.5'`.
- `Money.fromDecimalString('1.005', 'USD')` **throws** instead of guessing a rounding. If an upstream system hands you a sub-cent amount, that is a data problem to surface, not to hide.
- `Money.fromDecimalString('100.5', 'JPY')` throws as well, which catches a classic bug where a USD-shaped amount is sent for a zero-decimal currency.

For tests and fixtures, `Money.ofMinor(1050, 'USD')` or `Money.fromDecimalString('10.50', 'USD')` are both readable enough, and neither can smuggle in a float.

## 3. Allocation without losing a cent

When you split a discount across lines, naive proportional rounding (`round(discount × weight / totalWeight)` for each line) makes the parts sum to the wrong total — usually off by a cent in either direction. The standard solution is the **largest remainder method**:

1. Give each part its exact share rounded **down**.
2. Count how many minor units are left over (it's always fewer than the number of parts).
3. Hand those leftover units out one at a time to the parts with the **largest fractional remainders**, breaking ties by position so the result is deterministic.

Here is an implementation using the same bigint discipline, and sign-symmetric like `divRound`:

```ts
// src/money/allocate.ts
import { Money } from './money';

/**
 * Splits `total` across `weights` so that the parts sum to exactly `total`.
 * Weights must be non-negative and not all zero.
 * allocate(-x, w) mirrors allocate(x, w) with signs flipped.
 */
export function allocate(total: Money, weights: readonly bigint[]): Money[] {
  if (weights.length === 0) {
    throw new RangeError('allocate: need at least one weight');
  }
  if (weights.some((w) => w < 0n)) {
    throw new RangeError('allocate: weights must be non-negative');
  }

  const weightSum = weights.reduce((a, b) => a + b, 0n);
  if (weightSum === 0n) {
    throw new RangeError('allocate: weights must not all be zero');
  }

  const negative = total.minor < 0;
  const magnitude = BigInt(Math.abs(total.minor));

  const shares = weights.map((w) => (magnitude * w) / weightSum);
  const remainders = weights.map((w) => (magnitude * w) % weightSum);

  const allocated = shares.reduce((a, b) => a + b, 0n);
  let leftover = magnitude - allocated;

  const order = weights
    .map((_, index) => index)
    .sort((a, b) => {
      if (remainders[a] !== remainders[b]) {
        return remainders[a] > remainders[b] ? -1 : 1;
      }
      return a - b;
    });

  for (const index of order) {
    if (leftover === 0n) break;
    shares[index] += 1n;
    leftover -= 1n;
  }

  return shares.map((share) =>
    Money.ofMinor(Number(negative ? -share : share), total.currency),
  );
}
```

Properties worth asserting in tests:

- **Conservation**: the parts sum to exactly `total.minor`, for every input.
- **Fairness**: no part differs from its exact proportional share by a full minor unit or more.
- **Mirror**: `allocate(total.negate(), w)` equals the element-wise negation of `allocate(total, w)`. (You'll want a `negate()` on `Money`; it's a one-liner.)
- **Zero weights get zero** unless leftover units are distributed to them, which can't happen because a zero weight has a zero remainder and the sort puts it last. The loop stops once `leftover` hits zero, and leftover is always smaller than the count of non-zero-weight parts.

A usage sketch for your discount case: the weights are each line's pre-discount subtotal in minor units, so a discount of 10.00 across three lines is shared proportionally, the discount is subtracted per line, and then tax is computed on each *discounted* line subtotal. Tax is therefore correct per line, and the invoice totals still equal the sum of the lines.

```ts
const weights = lines.map((l) => BigInt(l.subtotal.minor));
const shares = allocate(invoiceDiscount, weights);
const discounted = lines.map((l, i) => l.subtotal.subtract(shares[i]));
```

One question to settle with finance: when two lines have identical remainders, my tie-break gives the extra cent to the **earlier** line. That is arbitrary but stable. If they have a rule (for example, "largest line first"), the comparator is the only thing that changes. Also confirm whether a discount may exceed a line's subtotal, since proportional allocation guarantees it can't unless the total discount exceeds the sum of all lines, which would be worth rejecting up front.

# Wiring it in: calculator, tests, and the database plan

This answer has three parts: the new calculator, a test suite built around the properties finance cares about, and an additive database path that never recomputes an issued invoice.

## The calculator

Inputs change shape: `unitPrice` is a `Money`, while `quantity` and `taxPercent` are decimal strings parsed into exact `Ratio`s. The rounding policy lives in one named constant so that anyone reading the code (or finance reading a diff) can see it in one place.

```ts
// src/invoices/calculator.ts
import { Money } from '../money/money';
import { Ratio } from '../money/ratio';
import { RoundingMode } from '../money/rounding';
import { allocate } from '../money/allocate';
import { CurrencyCode } from '../money/currency';

export const ROUNDING_POLICY = {
  lineSubtotal: 'half-away-from-zero',
  lineTax: 'half-away-from-zero',
} as const satisfies Record<string, RoundingMode>;

export interface LineInput {
  description: string;
  unitPrice: Money;
  quantity: string;   // exact decimal, e.g. '2.5'
  taxPercent: string; // exact decimal percent, e.g. '8.875'
}

export interface LineResult {
  description: string;
  subtotal: Money;
  tax: Money;
  total: Money;
}

export interface InvoiceResult {
  currency: CurrencyCode;
  lines: LineResult[];
  subtotal: Money;
  tax: Money;
  total: Money;
}

export function calculateLine(
  input: LineInput,
  discount: Money = Money.zero(input.unitPrice.currency),
): LineResult {
  const gross = input.unitPrice.multiply(
    Ratio.fromDecimalString(input.quantity),
    ROUNDING_POLICY.lineSubtotal,
  );
  const subtotal = gross.subtract(discount);
  const tax = subtotal.multiply(
    Ratio.fromPercentString(input.taxPercent),
    ROUNDING_POLICY.lineTax,
  );

  return {
    description: input.description,
    subtotal,
    tax,
    total: subtotal.add(tax), // exact: never rounded
  };
}

export function calculateInvoice(
  items: readonly LineInput[],
  currency: CurrencyCode,
  invoiceDiscount: Money = Money.zero(currency),
): InvoiceResult {
  if (items.some((i) => i.unitPrice.currency !== currency)) {
    throw new TypeError('calculateInvoice: line currency differs from invoice');
  }

  const grossSubtotals = items.map((item) =>
    item.unitPrice.multiply(
      Ratio.fromDecimalString(item.quantity),
      ROUNDING_POLICY.lineSubtotal,
    ),
  );

  const shares = invoiceDiscount.isZero()
    ? grossSubtotals.map(() => Money.zero(currency))
    : allocate(invoiceDiscount, grossSubtotals.map((g) => BigInt(g.minor)));

  const lines = items.map((item, i) => calculateLine(item, shares[i]));

  const zero = Money.zero(currency);
  return {
    currency,
    lines,
    subtotal: lines.reduce((acc, l) => acc.add(l.subtotal), zero),
    tax: lines.reduce((acc, l) => acc.add(l.tax), zero),
    total: lines.reduce((acc, l) => acc.add(l.total), zero),
  };
}
```

Notes on the choices:

- `calculateLine` computes the gross amount a second time inside `calculateInvoice` (once for the allocation weights, once inside the line). That is a deliberate trade for clarity; the multiplication is cheap, and the function stays usable on its own. If you'd rather pass the gross in, it's a trivial change.
- `satisfies Record<string, RoundingMode>` keeps the literal types narrow while still checking each entry, so a typo in a mode name is a compile error.
- Invoice totals are reductions over integer `Money`, so `total === subtotal + tax` holds for the invoice **because it holds for each line**. There is no remaining place that can disagree.
- The discount reduces the subtotal *before* tax, so tax is computed on the discounted amount. If any customers have jurisdictions where tax applies to the pre-discount amount, that is a policy flag on the line, not something to bury in this function.
- When `allocate` is given a gross subtotal total of zero (every line free), it throws. Handle that by returning zero shares when the sum of weights is zero, or by rejecting a non-zero discount on a zero invoice. I'd reject it, since a discount with nothing to discount is more likely a data error.

## Tests finance will recognize

Two kinds: **example tests** with numbers a person can verify by hand, and **property tests** that state the invariants across thousands of generated cases. The second kind uses `fast-check`. That is a dev dependency only, which keeps the runtime dependency-free as you asked.

```ts
// src/invoices/calculator.test.ts
import { describe, expect, it } from 'vitest';
import fc from 'fast-check';
import { Money } from '../money/money';
import { calculateInvoice, calculateLine } from './calculator';

const usd = (text: string) => Money.fromDecimalString(text, 'USD');

describe('calculateLine: hand-checked examples', () => {
  it('rounds a half-cent subtotal up (the original bug)', () => {
    const price = Money.ofMinor(1005, 'USD'); // 10.05 per unit
    const line = calculateLine({
      description: 'tenth of a unit',
      unitPrice: price,
      quantity: '0.1',
      taxPercent: '0',
    });
    // 10.05 x 0.1 = 1.005 -> 1.01
    expect(line.subtotal.minor).toBe(101);
  });

  it('rounds tax per line on the rounded subtotal', () => {
    const line = calculateLine({
      description: 'widget',
      unitPrice: usd('14.00'),
      quantity: '1',
      taxPercent: '8.25',
    });
    // 14.00 x 8.25% = 1.155 -> 1.16
    expect(line.tax.toDecimalString()).toBe('1.16');
    expect(line.total.toDecimalString()).toBe('15.16');
  });

  it('uses zero decimals for JPY and three for KWD', () => {
    const yen = calculateLine({
      description: 'yen',
      unitPrice: Money.ofMinor(999, 'JPY'),
      quantity: '1',
      taxPercent: '10',
    });
    expect(yen.tax.minor).toBe(100); // 99.9 -> 100

    const kwd = calculateLine({
      description: 'kwd',
      unitPrice: Money.fromDecimalString('1.005', 'KWD'),
      quantity: '1',
      taxPercent: '5',
    });
    expect(kwd.tax.toDecimalString()).toBe('0.050'); // 0.05025 -> 0.050
  });
});

describe('invariants', () => {
  const lineArb = fc.record({
    description: fc.constant('line'),
    unitPrice: fc.integer({ min: 0, max: 5_000_000 }).map((m) => Money.ofMinor(m, 'USD')),
    quantity: fc
      .tuple(fc.integer({ min: 0, max: 500 }), fc.integer({ min: 0, max: 999 }))
